@Event340:
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("杀机.mp3");
	LoadMap("map063_华山派大厅.map");
	LoadNpc("map063.npc");  
	LoadObj("map063.obj");
	SetPlayerPos(5, 42);
	SetPlayerDir(5);
	FadeIn();
	
	MoveScreen(5, 100, 2);
	Say("林海：各位江湖同道：今日胜负已决，在下侥幸得到掌门之位，结束了我华山派数年来群龙无首的局面。林某今后定当尽心竭力，将华山一派发扬光大。", 72);
	Say("林海：林某绝非贪图区区掌门之位，只是华山派在顾师兄手中已经日渐凋敝。刚才大家也亲眼见到，在下论武功，论才智，都胜了顾师兄一筹，林某相信华山派今后一定会更加昌盛。", 72);
	Say("林海：不过，非常遗憾的是，比武时林某不慎出手太重，导致师兄伤重不治而亡，虽说决斗前有诸位作证，我们立下生死文书，死伤不究，但林某仍然感到十分难过，故而决定为师兄守灵七七四十九天，以尽我兄弟之情分。", 72);
	Say("林海：有劳各位远道而来，本来应该好好款待，没想到师兄出了意外，只好等我师兄七七之后再来答谢诸位了。", 72);
	Sleep(500);
	Say("独孤剑：什么？顾大侠死了！怎么会这么巧？", 6);
	Sleep(500);
	Say("林海：阁下是什么人，为何在我华山派大厅无端喧哗？", 72);
	
	SetPlayerScn();
	PlayerGoto(12, 28);
	SetPlayerDir(5);
	SetNpcKind("张琳心", 1);
	NpcGoto("张琳心", 12, 30);
	SetNpcDir("张琳心", 4);
	Say("独孤剑：在下衡山独孤剑，本来有要事要见顾大侠，没想到顾大侠他……", 1);
	Say("林海：原来是刘老爷子的高足，不知有什么要事要跟我师兄说？师兄已经不在了，林某现在掌管华山派，你有什么话就跟我说吧。", 72);
	Say("独孤剑：嗯……家师临终前得到五色教的一份暗杀名单……", 1);
	Say("林海：荒唐！五色教早已被我武林正派剿杀干净，几十年来销声匿迹，哪里还有什么五色教之说！当年我华山派也曾出过大力，还折了不少精英，那时你们这些娃儿还没出世呢！", 72);
	Sleep(500);
	NpcGoto("方勉", 11, 27);
	SetNpcDir("方勉", 6);
	Say("方勉：林掌门不必和后辈动怒，且听他们将事情的原委说清楚。", 50);
	SetNpcDir("方勉", 7);
	Say("方勉：你们且把事情的原委当着各位江湖同道的面说清楚。", 50);
	Sleep(500);
	Say("独孤剑：这……家师临终前得到五色教的一份暗杀名册，上写明九月初五杀死武夷山柳中原柳前辈，柳前辈果然在那天被人围攻不敌而死。名册上写明今天对顾大侠下手，没想到顾大侠就……", 1);
	Say("林海：越说越不象话了！老夫和师兄公开比武，有这么多武林高人作证，难道说是老夫暗杀了我师兄不成？你把在座的各位当做什么人了？刘轻舟堂堂一派掌门，难道他教出的就是你这种到处胡说八道的弟子？", 72);
	Say("独孤剑：在下句句实言。", 1);
	Say("林海：你说你是衡山弟子，可有我华山派送去的请帖？", 72);
	Say("独孤剑：这个……晚辈因下山较早，没有接到贵派的请帖。", 1);
	Say("林海：这就奇了，我华山派今日的比武大会乃是天下武林皆知的大事，你堂堂衡山派怎会不知？再者，我华山派地处金人势力之中，素以抗金大业为己任，为防止金人上山，华山各要道防守甚严，你既然没有本派的请帖，又如何上得山来？莫非你是金人派来的？", 72);
	Say("张琳心：林大侠这是什么意思？我们好心好意千里迢迢来给你们华山派报信，你却反诬赖我们是金国奸细？独孤哥哥，别理他了，既然顾大侠已遭不测，我们要尽快通知其他人。走！", 27);
	Say("林海：走？你当我华山派是什么地方，想来就来，说走就走？你一个女孩儿家不好好在家呆着，跟着一个男人在外惹是生非，我看你们根本就不是什么好人，哼！老夫今天就杀了你们这几个金国奸细！", 72);
	Say("张琳心：你……", 27);
	Sleep(500);
	SetNpcDir("方勉", 6);
	Say("方勉：林大侠且慢！听方某说两句。", 50);
	Say("方勉：这位是“仙剑客”独孤云的公子，刘轻舟的高足，现为衡山掌门；那位姑娘是“飞剑客”张风的千金，方某曾在临安与他们有过一面之交，可以担保他们不是金国奸细。", 50);
	Say("方勉：两个晚辈出言不逊冲撞林大侠，还望林大侠展示长辈风范，不要与他们动手。", 50);
	Say("林海：这……既然有方大侠为你们担保，老夫就暂不追究你们擅闯华山之罪。来者是客，两位若要坐下喝老夫一杯水酒，林某也欢迎之至。", 72);
	Say("张琳心：哼！谁稀罕你的酒！独孤哥哥，我们走！", 27);
	Say("独孤剑：方大侠，林掌门，独孤剑多有得罪。", 1);
	SetNpcKind("张琳心", 3);
	PlayerGoto(7, 38);
	SetPlayerDir(1);
	Assign($Event, 350);
	Memo("独孤剑和张琳心来到华山派大厅，比武已经结束，华山掌门顾枫被师弟林海打死，独孤剑觉得此事蹊跷，林海反说他们是金国来的奸细，幸得方勉担保二人才得以全身而退。");
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map048_华山脚下.map");
	LoadNpc("map048.npc");
	DelNpc("华山派弟子");
	SaveNpc();
	LoadObj("map048.obj");
	SetPlayerPos(5, 68);
	SetPlayerDir(7);
	SetNpcKind("张琳心", 1);
	SetNpcPos("张琳心", 6, 68);
	SetNpcDir("张琳心", 1);	
	FadeIn();
	Say("张琳心：哼！", 23);
	Say("独孤剑：还在为刚才的事生气？", 1);
	Say("张琳心：这个林海我越看越可疑，他早不比武，晚不比武，偏偏选在今天……", 23);
	Say("独孤剑：我也觉得他有些可疑……", 1);
	Say("张琳心：岂止可疑，简直可恶！", 23);
	Sleep(500);
	Say("张琳心：对了！独孤哥哥，还记得刚才上山时碰到的那两个华山弟子吗？其中一个姓林的，好像与林海有什么关系，我们不如去长安找他，说不定能从他身上打听一些内情。", 21);
	Say("独孤剑：也好，我们这就去长安找他。", 1);
	StopMusic();
	PlayMusic("长路.mp3");
	SetNpcKind("张琳心", 3);
	Assign($Event, 360);
	Memo("独孤剑和张琳心下到华山脚下，想起上山时碰到的华山派弟子，猜测此人可能知道一些内幕，于是两人决定去长安妓院找他。");
	Return;

@Event368:
	Return;
	
@Event370:
	FadeOut();
	SaveNpc();
	ClearBody();
	SaveObj();
	LoadMap("map063_华山派大厅.map");
	LoadObj("map063.obj");
	SetPlayerPos(5, 42);
